// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

interface IERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
}

/// @notice Share-based vault hardened against the "donation" / share-price
/// inflation attack.
///
/// Two independent defenses:
///  1. Internal asset accounting (`totalAssets`) instead of
///     `asset.balanceOf(address(this))`. A direct token transfer into the vault
///     no longer moves the exchange rate, so the attacker's donation is simply
///     a gift to nobody and cannot be used to round a victim's mint down.
///  2. A virtual shares/assets offset (ERC-4626 style): the rate is computed
///     against `totalShares + VIRTUAL_SHARES` over `totalAssets + 1`, which
///     keeps the price finite and bounded even in edge states, so the very
///     first depositor cannot be front-run into a 1-wei share supply that
///     makes each share arbitrarily expensive.
///
/// Rounding always favors the vault (shares round down on deposit, assets
/// round down on withdraw) and a mint of zero shares reverts, so a deposit can
/// never silently vanish.
contract Vault {
    IERC20 public immutable asset;

    /// @dev Virtual share offset. Deposits mint ~1000x the raw asset amount in
    /// shares, making a "1 wei of shares is worth the whole vault" state
    /// unreachable in practice.
    uint256 private constant VIRTUAL_SHARES = 1000;

    uint256 public totalShares;
    /// @dev Assets the vault actually accounts for. Deliberately NOT
    /// `balanceOf(this)`: unsolicited transfers must not affect the rate.
    uint256 public totalAssets;

    mapping(address => uint256) public shares;

    error ZeroShares();
    error ZeroAssets();
    error TransferFailed();

    constructor(address _asset) {
        asset = IERC20(_asset);
    }

    function convertToShares(uint256 amount) public view returns (uint256) {
        return (amount * (totalShares + VIRTUAL_SHARES)) / (totalAssets + 1);
    }

    function convertToAssets(uint256 s) public view returns (uint256) {
        return (s * (totalAssets + 1)) / (totalShares + VIRTUAL_SHARES);
    }

    function deposit(uint256 amount) external returns (uint256 s) {
        s = convertToShares(amount);
        if (s == 0) revert ZeroShares();

        shares[msg.sender] += s;
        totalShares += s;
        totalAssets += amount;

        _pull(msg.sender, amount);
    }

    function withdraw(uint256 s) external returns (uint256 amount) {
        amount = convertToAssets(s);
        if (amount == 0) revert ZeroAssets();

        // Reverts on insufficient balance (checked arithmetic).
        shares[msg.sender] -= s;
        totalShares -= s;
        totalAssets -= amount;

        _push(msg.sender, amount);
    }

    function _pull(address from, uint256 amount) private {
        (bool ok, bytes memory data) = address(asset).call(
            abi.encodeCall(IERC20.transferFrom, (from, address(this), amount))
        );
        if (!ok || (data.length != 0 && !abi.decode(data, (bool)))) revert TransferFailed();
    }

    function _push(address to, uint256 amount) private {
        (bool ok, bytes memory data) = address(asset).call(
            abi.encodeCall(IERC20.transfer, (to, amount))
        );
        if (!ok || (data.length != 0 && !abi.decode(data, (bool)))) revert TransferFailed();
    }
}
