// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @dev Minimal ERC20 surface used to talk to the underlying asset.
interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

/// @title Vault
/// @notice Yield-bearing share vault. Yield arrives as a plain transfer of the
///         asset to this contract, so `totalAssets()` is simply the live asset
///         balance -- any donation is immediately owned pro-rata by existing
///         shareholders.
///
/// Rounding / attack policy:
///  - `deposit` rounds shares DOWN, `redeem` rounds assets DOWN. Every rounding
///    error therefore stays in the vault (it can never favour the caller), which
///    is what makes an instant deposit->redeem round trip non-profitable and
///    keeps the vault solvent for all holders in any redemption order.
///  - The exchange rate is computed against a virtual pool of
///    `VIRTUAL_SHARES` shares backed by 1 virtual wei of assets. Those virtual
///    units are owned by nobody, so a first depositor cannot own 1 share worth
///    the whole balance: the classic donation / inflation attack would require
///    the attacker to gift ~VIRTUAL_SHARES times the victim's deposit, and every
///    wei of that gift is captured by the victim rather than the attacker.
///    Deposits that would mint zero shares for a non-zero amount revert, so a
///    depositor can never be rounded down to nothing.
contract Vault {
    /* ------------------------------- immutables ------------------------------ */

    /// @notice The underlying asset held by the vault.
    address public immutable asset;

    /// @notice Virtual shares backing 1 virtual wei of assets (10 ** 12 offset).
    ///         Large enough to price the inflation attack out of existence,
    ///         small enough that share supply cannot overflow for any sane token.
    uint256 public constant VIRTUAL_SHARES = 1e12;

    /* ------------------------------ share token ------------------------------ */

    string public name = "Vault Share";
    string public symbol = "vSHARE";
    uint8 public immutable decimals;

    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    /* -------------------------------- events -------------------------------- */

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event Deposit(address indexed caller, uint256 assets, uint256 shares);
    event Redeem(address indexed caller, uint256 assets, uint256 shares);

    /* ------------------------------ reentrancy ------------------------------ */

    uint256 private _locked = 1;

    modifier nonReentrant() {
        require(_locked == 1, "REENTRANCY");
        _locked = 2;
        _;
        _locked = 1;
    }

    /* ------------------------------ constructor ----------------------------- */

    constructor(address _asset) {
        require(_asset != address(0), "ZERO_ASSET");
        asset = _asset;

        // Share decimals = asset decimals + offset, when the asset reports them.
        uint8 assetDecimals = 18;
        (bool ok, bytes memory data) = _asset.staticcall(abi.encodeWithSignature("decimals()"));
        if (ok && data.length >= 32) {
            uint256 d = abi.decode(data, (uint256));
            if (d <= 36) assetDecimals = uint8(d);
        }
        decimals = assetDecimals + 12; // 12 == log10(VIRTUAL_SHARES)
    }

    /* -------------------------------- accounting ---------------------------- */

    /// @notice Total assets under management: the live balance, so a plain
    ///         transfer in is yield the moment it lands.
    function totalAssets() public view returns (uint256) {
        return IERC20(asset).balanceOf(address(this));
    }

    /// @notice Shares minted for `assets` at the current price (rounded down).
    function convertToShares(uint256 assets) public view returns (uint256) {
        return (assets * (totalSupply + VIRTUAL_SHARES)) / (totalAssets() + 1);
    }

    /// @notice Assets owed for `shares` at the current price (rounded down).
    ///         Strictly less than `totalAssets() + 1` for any `shares <=
    ///         totalSupply`, hence never more than the vault holds.
    function convertToAssets(uint256 shares) public view returns (uint256) {
        return (shares * (totalAssets() + 1)) / (totalSupply + VIRTUAL_SHARES);
    }

    /// @notice What `owner` could withdraw right now.
    function maxWithdraw(address owner) external view returns (uint256) {
        return convertToAssets(balanceOf[owner]);
    }

    /* ---------------------------------- core -------------------------------- */

    /// @notice Pull `assets` from the caller and mint the corresponding shares.
    function deposit(uint256 assets) external nonReentrant returns (uint256 shares) {
        // Price is read BEFORE the transfer in, so the caller's own deposit does
        // not dilute the rate it is quoted at.
        shares = convertToShares(assets);
        require(shares != 0 || assets == 0, "ZERO_SHARES");

        _pull(msg.sender, assets);

        totalSupply += shares;
        balanceOf[msg.sender] += shares;

        emit Transfer(address(0), msg.sender, shares);
        emit Deposit(msg.sender, assets, shares);
    }

    /// @notice Burn `shares` and pay out the corresponding assets.
    function redeem(uint256 shares) external nonReentrant returns (uint256 assets) {
        assets = convertToAssets(shares);

        // Reverts on insufficient balance (checked arithmetic).
        balanceOf[msg.sender] -= shares;
        totalSupply -= shares;

        emit Transfer(msg.sender, address(0), shares);
        emit Redeem(msg.sender, assets, shares);

        _push(msg.sender, assets);
    }

    /* ------------------------------- share ERC20 ---------------------------- */

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        emit Transfer(msg.sender, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        if (allowed != type(uint256).max) {
            allowance[from][msg.sender] = allowed - amount;
        }
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        emit Transfer(from, to, amount);
        return true;
    }

    /* ------------------------------ asset moves ----------------------------- */

    function _pull(address from, uint256 amount) private {
        (bool ok, bytes memory data) = asset.call(
            abi.encodeWithSelector(IERC20.transferFrom.selector, from, address(this), amount)
        );
        require(ok && (data.length == 0 || abi.decode(data, (bool))), "TRANSFER_FROM_FAILED");
    }

    function _push(address to, uint256 amount) private {
        (bool ok, bytes memory data) = asset.call(
            abi.encodeWithSelector(IERC20.transfer.selector, to, amount)
        );
        require(ok && (data.length == 0 || abi.decode(data, (bool))), "TRANSFER_FAILED");
    }
}
